import logging
from taf.ul.mobile.ui.android.executor import SshExecutor
from taf.ul.mobile.ui.android.available_mobiles import SupportedMobiles
from taf.ul.mobile.ui.android.available_adb_proxies import SupportedAdbProxies


class MobileFactory(object):

    def create(self, ui_version, host, username, password, port, serial_number):
        executor_config = {"host": host, "user": username, "password": password, "port": port}

        android_version, brand, model = self._detect_android_version_brand_model(executor_config, serial_number)

        executor = SshExecutor(**executor_config)
        adb_proxy = AdbProxyFactory().create(
            executor=executor, serial_number=serial_number, android_version=android_version)

        logging.info("create mobile with ui_version={} brand={} model={}".format(ui_version, brand, model))
        return SupportedMobiles().get_mobile(ui_version, brand, model)(adb_proxy)

    def _detect_android_version_brand_model(self, executor_config, serial_number):
        executor = SshExecutor(**executor_config)
        adb_proxy = AdbProxyFactory().create(executor=executor, serial_number=serial_number)
        adb_proxy.setup()
        android_version = adb_proxy.get_android_version()
        brand = adb_proxy.get_brand()
        model = adb_proxy.get_model()
        adb_proxy.teardown()
        return android_version, brand, model


class AdbProxyFactory(object):

    @staticmethod
    def create(executor, serial_number, android_version=""):
        logging.info("create adb proxy for android version={}".format(android_version))
        return SupportedAdbProxies()[android_version](executor, serial_number)
